import { useState, useEffect } from "react";
import { getUser, updateLimits, getTaps } from "../api";
import { useAuth } from "../context/AuthContext";

export default function SystemSetup() {
  const { user }          = useAuth();
  const uid               = user?.user_id;
  const [profile, setProfile] = useState(null);
  const [taps,    setTaps]    = useState([]);
  const [form,    setForm]    = useState({ green_limit:"", orange_limit:"" });
  const [msg,     setMsg]     = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    (async () => {
      try {
        const [u, t] = await Promise.all([getUser(uid), getTaps(uid)]);
        setProfile(u.data);
        setTaps(t.data);
        setForm({ green_limit: u.data.green_limit, orange_limit: u.data.orange_limit });
      } catch(e) { console.error(e); }
    })();
  }, [uid]);

  const save = async (e) => {
    e.preventDefault();
    if (+form.green_limit >= +form.orange_limit) {
      setMsg("❌ Green limit must be less than Orange limit");
      return;
    }
    setLoading(true); setMsg("");
    try {
      await updateLimits(uid, {
        green_limit:  +form.green_limit,
        orange_limit: +form.orange_limit,
      });
      setMsg("✅ Limits saved successfully!");
      setProfile(p => ({ ...p, ...form }));
    } catch(err) {
      setMsg("❌ " + (err.response?.data?.error || "Failed to save"));
    } finally { setLoading(false); }
  };

  return (
    <div style={{ color:"#e2e8f0", fontFamily:"'DM Sans',sans-serif" }}>
      <div style={{ marginBottom:32 }}>
        <h1 style={{ fontSize:28, fontWeight:800, margin:0,
          background:"linear-gradient(90deg,#00d4ff,#0057ff)",
          WebkitBackgroundClip:"text", WebkitTextFillColor:"transparent" }}>
          System Setup
        </h1>
        <p style={{ color:"#4a7fa5", marginTop:4, fontSize:14 }}>
          Configure usage limits and review system information
        </p>
      </div>

      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:24, marginBottom:24 }}>
        {/* User Profile Card */}
        <Card title="👤 User Profile">
          {profile && (
            <div style={{ display:"flex", flexDirection:"column", gap:14 }}>
              <InfoRow label="Name"        value={profile.name} />
              <InfoRow label="Email"       value={profile.email} />
              <InfoRow label="User ID"     value={`#${profile.user_id}`} />
              <InfoRow label="Member Since" value={profile.created_at?.substring(0,10)} />
              <InfoRow label="Total Taps"  value={taps.length} />
            </div>
          )}
        </Card>

        {/* Alert Limits Form */}
        <Card title="🚨 Usage Alert Limits">
          <p style={{ color:"#4a7fa5", fontSize:13, marginBottom:20 }}>
            Set daily usage thresholds for color-coded alerts. These determine
            when the status indicator turns Orange or Red on your dashboard.
          </p>
          <form onSubmit={save}>
            <div style={{ display:"flex", gap:12, marginBottom:16 }}>
              <div style={{ flex:1 }}>
                <label style={labelStyle}>🟢 Green Limit (L/day)</label>
                <input
                  type="number" min="1" step="0.5" required
                  value={form.green_limit}
                  onChange={e => setForm(p => ({ ...p, green_limit:e.target.value }))}
                  style={inputStyle}
                />
                <div style={{ color:"#4a7fa5", fontSize:11, marginTop:4 }}>
                  Below this = green (safe)
                </div>
              </div>
              <div style={{ flex:1 }}>
                <label style={labelStyle}>🟠 Orange Limit (L/day)</label>
                <input
                  type="number" min="1" step="0.5" required
                  value={form.orange_limit}
                  onChange={e => setForm(p => ({ ...p, orange_limit:e.target.value }))}
                  style={inputStyle}
                />
                <div style={{ color:"#4a7fa5", fontSize:11, marginTop:4 }}>
                  Above this = red (critical)
                </div>
              </div>
            </div>

            {/* Visual limit scale */}
            <div style={{ marginBottom:20 }}>
              <div style={{ display:"flex", height:10, borderRadius:5, overflow:"hidden" }}>
                <div style={{ flex:+form.green_limit, background:"#00d97e80" }}/>
                <div style={{ flex:+form.orange_limit - +form.green_limit, background:"#ff9d0080" }}/>
                <div style={{ flex:20, background:"#ff4d6d80" }}/>
              </div>
              <div style={{ display:"flex", justifyContent:"space-between",
                color:"#4a7fa5", fontSize:10, marginTop:4 }}>
                <span>0</span>
                <span style={{ color:"#00d97e" }}>Green &lt; {form.green_limit}L</span>
                <span style={{ color:"#ff9d00" }}>Orange &lt; {form.orange_limit}L</span>
                <span style={{ color:"#ff4d6d" }}>Red ↑</span>
              </div>
            </div>

            {msg && (
              <div style={{
                padding:"10px 14px", borderRadius:8, fontSize:13, marginBottom:12,
                background: msg.startsWith("✅") ? "#00d97e18" : "#ff4d4d18",
                border:`1px solid ${msg.startsWith("✅") ? "#00d97e40" : "#ff4d4d40"}`,
                color: msg.startsWith("✅") ? "#00d97e" : "#ff6b6b",
              }}>{msg}</div>
            )}

            <button type="submit" disabled={loading} style={btnStyle}>
              {loading ? "Saving…" : "💾 Save Limits"}
            </button>
          </form>
        </Card>
      </div>

      {/* Taps overview */}
      <Card title="🚿 Registered Taps">
        {taps.length === 0 ? (
          <p style={{ color:"#4a7fa5" }}>No taps added yet. Go to Tap Management.</p>
        ) : (
          <div style={{ overflowX:"auto" }}>
            <table style={{ width:"100%", borderCollapse:"collapse", fontSize:13 }}>
              <thead>
                <tr>
                  {["ID","Tap Name","Location","Status","Usage Today"].map(h => (
                    <th key={h} style={{ color:"#4a7fa5", textAlign:"left",
                      padding:"8px 12px", borderBottom:"1px solid #1e2a45",
                      fontSize:11, fontWeight:600, letterSpacing:0.6 }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {taps.map(t => (
                  <tr key={t.tap_id}>
                    <td style={td}>#{t.tap_id}</td>
                    <td style={{ ...td, color:"#e2e8f0", fontWeight:600 }}>{t.tap_name}</td>
                    <td style={td}>{t.location}</td>
                    <td style={td}>
                      <span style={{
                        padding:"2px 10px", borderRadius:20, fontSize:11, fontWeight:700,
                        background: t.tap_status==="ON" ? "#00d97e20" : "#4a7fa520",
                        color:      t.tap_status==="ON" ? "#00d97e"   : "#4a7fa5",
                      }}>{t.tap_status}</span>
                    </td>
                    <td style={{ ...td, color:"#00d4ff", fontWeight:700 }}>
                      {(t.current_usage||0).toFixed(2)} L
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>

      {/* Architecture info */}
      <Card title="🏗️ System Architecture">
        <div style={{ display:"grid", gridTemplateColumns:"repeat(5,1fr)", gap:0 }}>
          {[
            { icon:"🚿", label:"Tap Control",    sub:"Manual ON/OFF" },
            { icon:"🐍", label:"Flask Backend",   sub:"REST API" },
            { icon:"🤖", label:"Simulator",       sub:"Adds usage/60s" },
            { icon:"🗄️", label:"MySQL DB",        sub:"All data stored" },
            { icon:"⚛️", label:"React Frontend",  sub:"Live dashboard" },
          ].map((item, i, arr) => (
            <div key={i} style={{ display:"flex", alignItems:"center" }}>
              <div style={{ textAlign:"center", flex:1 }}>
                <div style={{ fontSize:28, marginBottom:4 }}>{item.icon}</div>
                <div style={{ color:"#e2e8f0", fontSize:12, fontWeight:700 }}>{item.label}</div>
                <div style={{ color:"#4a7fa5", fontSize:10 }}>{item.sub}</div>
              </div>
              {i < arr.length-1 && (
                <div style={{ color:"#00d4ff", fontSize:20, padding:"0 4px" }}>→</div>
              )}
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
}

function Card({ title, children }) {
  return (
    <div style={{ background:"#0d1220", border:"1px solid #1e2a45",
      borderRadius:16, padding:28, marginBottom:0 }}>
      <div style={{ color:"#e2e8f0", fontSize:16, fontWeight:700, marginBottom:20 }}>{title}</div>
      {children}
    </div>
  );
}

function InfoRow({ label, value }) {
  return (
    <div style={{ display:"flex", justifyContent:"space-between",
      padding:"8px 0", borderBottom:"1px solid #1e2a45" }}>
      <span style={{ color:"#4a7fa5", fontSize:13 }}>{label}</span>
      <span style={{ color:"#e2e8f0", fontSize:13, fontWeight:600 }}>{value}</span>
    </div>
  );
}

const labelStyle = {
  display:"block", color:"#94a3b8", fontSize:11,
  fontWeight:600, marginBottom:6, letterSpacing:0.8, textTransform:"uppercase",
};
const inputStyle = {
  width:"100%", padding:"10px 14px",
  background:"#0a0e1a", border:"1px solid #1e2a45",
  borderRadius:10, color:"#e2e8f0", fontSize:14,
  outline:"none", boxSizing:"border-box",
};
const btnStyle = {
  padding:"11px 28px",
  background:"linear-gradient(135deg,#00d4ff,#0057ff)",
  border:"none", borderRadius:10,
  color:"#fff", fontSize:14, fontWeight:700,
  cursor:"pointer",
};
const td = {
  padding:"10px 12px", color:"#94a3b8",
  borderBottom:"1px solid #1e2a45",
};
